#!/usr/bin/env python3
"""Overdue fee statements. Usage: fees.py INPUT_DIR OUTPUT_FILE"""
import csv
import io
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def read_text(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return f.read()


def read_csv(path):
    rows = csv.DictReader(io.StringIO(read_text(path), newline=""))
    out = []
    for r in rows:
        out.append({(k or "").strip(): (v or "").strip() for k, v in r.items() if k is not None})
    return out


def cents(s):
    return int((Decimal(s.strip()) * 100).to_integral_value())


def pnum(s):
    d = re.sub(r"\D", "", s or "")
    return int(d) if d else None


def parse_date(s):
    return date.fromisoformat(s.strip())


def parse_offset(s):
    m = re.fullmatch(r"([+-])(\d{1,2}):?(\d{2})", s.strip())
    sign = -1 if m.group(1) == "-" else 1
    return sign * (int(m.group(2)) * 60 + int(m.group(3)))


def parse_policy(path):
    sections = {}
    cur = None
    for line in read_text(path).splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("[") and line.endswith("]"):
            cur = line[1:-1].strip()
            sections[cur] = {}
            continue
        if "=" in line and cur is not None:
            k, v = line.split("=", 1)
            sections[cur][k.strip()] = v.strip()
    return sections


def main(indir, outfile):
    pol = parse_policy(os.path.join(indir, "policy.ini"))
    st = pol["statement"]
    library = st["library"]
    pstart = parse_date(st["period_start"])
    pend = parse_date(st["period_end"])

    clock = pol.get("clock", {})
    base_off = parse_offset(clock.get("offset", "+00:00"))
    changes = []
    for part in clock.get("changes", "").split(";"):
        part = part.strip()
        if not part:
            continue
        ts, off = part.split()
        t = datetime.strptime(ts, "%Y-%m-%dT%H:%MZ").replace(tzinfo=timezone.utc)
        changes.append((t, parse_offset(off)))
    changes.sort()

    def local_from_instant(t):
        off = base_off
        for ct, co in changes:
            if t >= ct:
                off = co
        return (t + timedelta(minutes=off)).replace(tzinfo=None)

    items = {}  # lower name -> (name, dict)
    cats = {}
    for name, sec in pol.items():
        if name.lower().startswith("item:"):
            n = name[5:].strip()
            items[n.lower()] = (n, {
                "loan_days": int(sec["loan_days"]), "renewals": int(sec["renewals"]),
                "grace": int(sec["grace_days"]), "daily": cents(sec["daily"]),
                "cap": cents(sec["loan_cap"])})
        elif name.lower().startswith("category:"):
            n = name[9:].strip()
            sc = sec.get("statement_cap", "none").strip()
            ex = {x.strip().lower() for x in sec.get("exempt", "").split(",") if x.strip()}
            cats[n.lower()] = (n, None if sc.lower() == "none" else cents(sc),
                               int(sec.get("discount", "0") or 0), ex)

    # branches and calendar
    branches = read_csv(os.path.join(indir, "branches.csv"))
    open_days = {}
    for b in branches:
        open_days[b["branch"]] = {d.lower()[:3] for d in b["open_days"].split()}
    cal = {}
    for r in read_csv(os.path.join(indir, "calendar.csv")):
        d = r["date"]
        if ".." in d:
            a, b = d.split("..")
        else:
            a = b = d
        cal.setdefault(r["branch"], []).append((parse_date(a), parse_date(b), r["status"].lower()))

    def is_open(branch, day):
        for key in (branch, "*"):
            for a, b, s in cal.get(key, []):
                if a <= day <= b:
                    return s == "open"
        return WEEKDAYS[day.weekday()] in open_days.get(branch, set())

    def next_open(branch, day):
        n = 0
        while not is_open(branch, day):
            day += timedelta(days=1)
            n += 1
            if n > 3700:
                break
        return day

    # patrons
    prow = {}
    for r in read_csv(os.path.join(indir, "patrons.csv")):
        prow.setdefault(pnum(r["patron"]), []).append((parse_date(r["since"]), r["category"], r["patron"]))
    for v in prow.values():
        v.sort(key=lambda x: x[0])

    def category_on(pn, day):
        rows = prow[pn]
        best = None
        for since, cat, _ in rows:
            if since <= day:
                best = cat
        if best is None:
            best = rows[0][1]
        return cats[best.lower()]

    # waivers
    waivers = []
    for r in read_csv(os.path.join(indir, "waivers.csv")):
        if r["status"].strip().lower() != "active":
            continue
        v = r["value"].strip()
        waivers.append((pnum(r["patron"]), r["loan"].strip(),
                        None if v.lower() == "full" else cents(v)))

    # events
    exdir = os.path.join(indir, "exports")
    events = {}
    for fn in sorted(os.listdir(exdir)):
        if not (fn.endswith(".csv") or fn.endswith(".jsonl")):
            continue
        path = os.path.join(exdir, fn)
        if not os.path.isfile(path):
            continue
        recs = []
        if fn.endswith(".csv"):
            for r in read_csv(path):
                r["_local"] = datetime.strptime(r["time"], "%Y-%m-%d %H:%M")
                recs.append(r)
        else:
            for line in read_text(path).splitlines():
                line = line.strip()
                if not line:
                    continue
                o = json.loads(line)
                r = {k: ("" if v is None else str(v).strip()) for k, v in o.items()}
                at = r["at"]
                if at.endswith("Z"):
                    at = at[:-1] + "+00:00"
                t = datetime.fromisoformat(at)
                if t.tzinfo is None:
                    t = t.replace(tzinfo=timezone.utc)
                r["_local"] = local_from_instant(t.astimezone(timezone.utc))
                recs.append(r)
        for r in recs:
            eid = r.get("event", "")
            if eid and eid not in events:
                events[eid] = r

    cancelled = set()
    for r in events.values():
        if r.get("type", "").lower() == "void":
            cancelled.add(r.get("target", ""))

    checkouts = {}
    others = {}
    for eid, r in events.items():
        if eid in cancelled:
            continue
        t = r.get("type", "").lower()
        if t == "checkout":
            checkouts[r["loan"]] = r
        elif t in ("renew", "return"):
            others.setdefault(r["loan"], []).append((r["_local"], t, r))

    loans = []
    for lid, c in checkouts.items():
        cd = c["_local"].date()
        if cd > pend:
            continue
        tname, ip = items[c["item_type"].lower()]
        br = c["branch"]
        due = next_open(br, cd + timedelta(days=ip["loan_days"]))
        nren = 0
        ret = None
        for lt, t, r in sorted(others.get(lid, []), key=lambda x: x[0]):
            if t == "renew":
                d = lt.date()
                if d <= due and nren < ip["renewals"] and d <= pend:
                    nren += 1
                    due = next_open(br, d + timedelta(days=ip["loan_days"]))
            else:
                ret = lt.date()
                if (r.get("via", "").lower() == "dropbox"):
                    ret -= timedelta(days=1)
                break
        if ret is not None and ret < pstart:
            continue
        if ret is not None and ret > pend:
            ret = None
        end = ret if ret is not None else pend
        od = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(br, d):
                od += 1
            d += timedelta(days=1)
        if od < 1:
            continue
        charged = od if od > ip["grace"] else 0
        pn = pnum(c["patron"])
        cname, scap, disc, exempt = category_on(pn, cd)
        base = charged * ip["daily"]
        if tname.lower() in exempt:
            base = 0
        base = min(base, ip["cap"])
        assessed = (base * (100 - disc) + 50) // 100
        app = [w for w in waivers if w[0] == pn and (w[1] == "*" or w[1] == lid)]
        if any(w[2] is None for w in app):
            waived = assessed
        else:
            waived = min(sum(w[2] for w in app), assessed)
        loans.append({"pn": pn, "loan": lid, "item": c.get("item", ""), "item_type": tname,
                      "branch": br, "checkout": cd, "due": due, "returned": ret,
                      "overdue_days": od, "charged_days": charged, "assessed": assessed,
                      "waived": waived, "capped": 0, "net": assessed - waived})

    bypatron = {}
    for l in loans:
        bypatron.setdefault(l["pn"], []).append(l)

    statements = []
    for pn in sorted(bypatron):
        ls = bypatron[pn]
        cap = category_on(pn, pend)
        scap = cap[1]
        if scap is not None:
            excess = sum(l["net"] for l in ls) - scap
            if excess > 0:
                order = sorted(ls, key=lambda l: (l["due"], l["loan"]), reverse=True)
                for l in order:
                    if excess <= 0:
                        break
                    g = min(l["net"], excess)
                    l["capped"] = g
                    excess -= g
        ls.sort(key=lambda l: (l["due"], l["loan"]))
        out_loans = []
        for l in ls:
            l["billed"] = l["net"] - l["capped"]
            out_loans.append({
                "loan": l["loan"], "item": l["item"], "item_type": l["item_type"],
                "branch": l["branch"], "checkout": l["checkout"].isoformat(),
                "due": l["due"].isoformat(),
                "returned": l["returned"].isoformat() if l["returned"] else None,
                "overdue_days": l["overdue_days"], "charged_days": l["charged_days"],
                "assessed": l["assessed"], "waived": l["waived"],
                "capped": l["capped"], "billed": l["billed"]})
        rows = prow[pn]
        pname = rows[-1][2]
        for since, cat, nm in rows:
            pname = nm
        s = {"patron": pname, "category": cap[0], "loans": out_loans}
        for k in ("assessed", "waived", "capped", "billed"):
            s[k] = sum(l[k] for l in ls)
        statements.append(s)

    bsum = []
    for b in branches:
        bl = [l for l in loans if l["branch"] == b["branch"]]
        e = {"branch": b["branch"], "loans": len(bl)}
        for k in ("charged_days", "assessed", "waived", "capped", "billed"):
            e[k] = sum(l[k] for l in bl)
        bsum.append(e)

    result = {"library": library, "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
              "statements": statements, "branches": bsum}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, indent=2, ensure_ascii=False)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
